127:     this.audio = new Audio();
128:     this.joystick = { x: 0, y: 0 };
129:     this.keys = new Set();
130:     this.state = defaultState();
131:     this.mode = 'title';
132:     this.paused = false;
133:     this.transitioning = false;
134:     this.sleeping = false;
135:     this.clock = new THREE.Clock();
136:     this.cameraYaw = 0.15;
137:     this.cameraPitch = 0.5;
