163:     const lowQ = isTouch() && (navigator.hardwareConcurrency || 4) <= 4;
164:     this.world = new World(this.scene, this.renderer, { lowQuality: lowQ });
165:     this.player = new Player(this.scene);
166:     this.slimes = new SlimeManager(this.scene, this.world);
167:     this.particles = new Particles(this.scene);
168:     this.ui = new UI(this);
169:     this.setupPost();
170:     this.setupInput();
171:     this.setupResize();
172: 
173:     this.player.setPosition(LAYOUT.spawn.x, this.world.height(LAYOUT.spawn.x, LAYOUT.spawn.z), LAYOUT.spawn.z);
174:     this.player.facing = Math.PI;
175:     this.player.group.rotation.y = Math.PI;
176:     this.world.updateSky(16.7);
177:     this.updateCamera(0, true);
