181: 
182:   // ---------------- setup ----------------
183:   setupRenderer() {
184:     this.renderer = new THREE.WebGLRenderer({
185:       canvas: this.canvas,
186:       antialias: !isTouch(),
187:       powerPreference: 'high-performance',
188:       alpha: false,
189:     });
190:     this.renderer.setPixelRatio(Math.min(devicePixelRatio || 1, isTouch() ? 1.5 : 1.8));
191:     this.renderer.setSize(innerWidth, innerHeight);
192:     this.renderer.shadowMap.enabled = true;
193:     this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
194:     this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
195:     this.renderer.toneMappingExposure = 1.08;
196:     this.renderer.outputColorSpace = THREE.SRGBColorSpace;
197:   }
198: 
199:   setupPost() {
200:     this.composer = new EffectComposer(this.renderer);
201:     this.composer.addPass(new RenderPass(this.scene, this.camera));
202:     const res = new THREE.Vector2(Math.max(1, innerWidth * 0.5), Math.max(1, innerHeight * 0.5));
203:     this.bloom = new UnrealBloomPass(res, isTouch() ? 0.42 : 0.5, 0.55, 0.86);
204:     this.composer.addPass(this.bloom);
205:     this.composer.addPass(new OutputPass());
206:     this.composer.setSize(innerWidth, innerHeight);
207:   }
208: 
209:   setupResize() {
210:     addEventListener('resize', () => {
211:       this.camera.aspect = innerWidth / innerHeight;
212:       this.camera.updateProjectionMatrix();
213:       this.renderer.setSize(innerWidth, innerHeight);
214:       this.composer.setSize(innerWidth, innerHeight);
215:       this.bloom.setSize(innerWidth * 0.5, innerHeight * 0.5);
216:     });
217:   }
218: 
219:   setupInput() {
220:     addEventListener('keydown', (e) => {
221:       if (e.code === 'Escape') {
222:         if (this.ui.modalKind) this.ui.closeModal();
223:         return;
224:       }
225:       if (this.mode !== 'play' || this.paused) return;
226:       if (['Space', 'KeyE', 'Digit1', 'Digit2', 'Digit3', 'KeyM'].includes(e.code)) e.preventDefault();
227:       this.keys.add(e.code);
228:       if (e.repeat) return;
229:       if (e.code === 'KeyE') this.doAction();
230:       if (e.code === 'Space') this.doAttack();
231:       if (e.code === 'Digit1') this.selectSeed('moon');
232:       if (e.code === 'Digit2') this.selectSeed('sun');
233:       if (e.code === 'Digit3') this.selectSeed('star');
234:       if (e.code === 'KeyM') this.ui.openMenu();
235:     });
236:     addEventListener('keyup', (e) => this.keys.delete(e.code));
237:     addEventListener('blur', () => this.keys.clear());
238: 
239:     const cv = this.renderer.domElement;
240:     cv.addEventListener('contextmenu', (e) => e.preventDefault());
241:     cv.addEventListener('pointerdown', (e) => {
242:       if (this.mode !== 'play' || this.paused) return;
243:       if (e.pointerType === 'mouse' && e.button !== 0) return;
244:       this.drag = { id: e.pointerId, x: e.clientX, y: e.clientY };
245:       try { cv.setPointerCapture(e.pointerId); } catch {}
246:     });
247:     cv.addEventListener('pointermove', (e) => {
248:       if (!this.drag || e.pointerId !== this.drag.id) return;
249:       const dx = e.clientX - this.drag.x;
250:       const dy = e.clientY - this.drag.y;
251:       this.drag.x = e.clientX; this.drag.y = e.clientY;
252:       this.cameraYaw -= dx * 0.0055;
253:       this.cameraPitch = clamp(this.cameraPitch + dy * 0.0028, 0.46, 1.02);
254:     });
255:     const dragEnd = (e) => {
256:       if (this.drag && e.pointerId === this.drag.id) this.drag = null;
257:     };
258:     cv.addEventListener('pointerup', dragEnd);
259:     cv.addEventListener('pointercancel', dragEnd);
260:     cv.addEventListener('wheel', (e) => {
261:       if (this.mode !== 'play') return;
262:       e.preventDefault();
263:       this.cameraDist = clamp(this.cameraDist + Math.sign(e.deltaY) * 1.2, 10, 26);
264:     }, { passive: false });
265: 
266:     addEventListener('beforeunload', () => { if (this.mode === 'play') this.save(); });
267:   }
268: 
269:   // ---------------- title / new game ----------------
270:   boot() {
271:     const hasSave = !!this.readSave();
272:     this.ui.showTitle(hasSave);
273:     this.mode = 'title';
274:     this.ui.setHudVisible(false);
275:     this.state.hours = 16.7;
276:     this.world.setWeather('clear');
277:     this.decorateTitleFarm();
278:     const note = document.getElementById('perf-note');
279:     note.textContent = 'The vale awaits…';
280:     setTimeout(() => note.classList.add('gone'), 1600);
281:     this.exposeDebug();
282:   }
283: 
284:   startNew() {
285:     localStorage.removeItem(SAVE_KEY);
286:     this.resetWorldState();
287:     this.state = defaultState();
288:     this.soundOn = true;
289:     this.audio.setMuted(false);
290:     this.beginPlay();
291:     this.ui.toast('Welcome to Emberfall Vale, farmer.', 'quest', '✦');
292:     setTimeout(() => this.ui.showHint('Walk onto the farm and press Use to till the soil.', 6500), 900);
293:     setTimeout(() => this.ui.toast('Zephyr the wizard trades to the east. The Moonwell glows to the west.', '', '🧭'), 5200);
294:     this.save();
295:   }
296: 
297:   continueGame() {
298:     const data = this.readSave();
299:     if (!data) { this.startNew(); return; }
300:     this.resetWorldState();
301:     this.loadState(data);
302:     this.beginPlay();
303:     this.ui.toast(`Welcome back. Day ${this.state.day} in the vale.`, 'quest', '✦');
304:   }
305: 
306:   decorateTitleFarm() {
307:     const picks = [
308:       [2, 2, 'moon', 2], [3, 2, 'moon', 2], [4, 2, 'moon', 1], [5, 2, 'sun', 1],
309:       [2, 3, 'sun', 3], [3, 3, 'moon', 1], [4, 3, 'sun', 2], [5, 3, 'moon', 2],
310:       [2, 4, 'star', 2], [3, 4, 'sun', 1], [4, 4, 'moon', 0], [5, 4, 'sun', 0],
311:     ];
312:     for (const [i, j, type, grown] of picks) {
313:       const p = this.world.plots[j * FARM.cols + i];
314:       if (!p) continue;
315:       p.tilled = true;
316:       p.watered = Math.random() < 0.5;
317:       p.crop = { type, grown, growDays: CROPS[type].grow, watered: p.watered };
318:       this.world.refreshPlot(p);
319:     }
320:     // a little trimmed path into the field, purely for the title view
321:     const p8 = this.world.plots[4 * FARM.cols + 1];
322:     if (p8) { p8.tilled = true; this.world.refreshPlot(p8); }
323:   }
324: 
325:   beginPlay() {
326:     this.mode = 'play';
327:     this.paused = false;
328:     this.ui.hideTitle();
329:     this.ui.setHudVisible(true);
330:     this.ui.sleepFade(false);
331:     this.audio.init();
332:     this.audio.setMuted(!this.soundOn);
333:     const px = this.state.playerPos?.x ?? LAYOUT.spawn.x;
334:     const pz = this.state.playerPos?.z ?? LAYOUT.spawn.z;
335:     this.player.setPosition(px, this.world.height(px, pz), pz);
336:     this.player.facing = this.state.playerFacing ?? Math.PI;
337:     this.player.group.rotation.y = this.player.facing;
338:     this.cameraYaw = 0.12;
339:     this.cameraPitch = 0.5;
340:     this.cameraDist = 14;
341:     this.updateCamera(0, true);
342:     this.updateTarget();
343:     this.ui.update(this.state);
344:   }
345: 
346:   resetWorldState() {
347:     for (const p of this.world.plots) {
348:       p.tilled = false; p.watered = false; p.crop = null;
349:       if (p.visual) { this.scene.remove(p.visual); p.visual = null; }
350:       this.world.updateSoilVisual(p);
351:     }
352:     for (const sp of this.world.sprinklers) this.scene.remove(sp.group);
353:     this.world.sprinklers.length = 0;
354:     this.world.newDay(1);
355:     this.world.day = 1;
356:     this.world.setWeather('clear');
357:     this.slimes.resetDay(1);
358:     this.invuln = 0;
359:     this.transitioning = false;
360:     this.sleeping = false;
361:   }
362: 
363:   // ---------------- save ----------------
364:   save() {
365:     if (this.mode !== 'play') return;
366:     const s = this.state;
367:     const data = {
368:       ...s,
369:       playerPos: { x: this.player.pos.x, z: this.player.pos.z },
370:       playerFacing: this.player.facing,
371:       plots: this.world.plots.map((p) => ({
372:         tilled: p.tilled,
373:         watered: p.watered,
374:         crop: p.crop ? { type: p.crop.type, grown: p.crop.grown } : null,
375:       })),
376:     };
377:     try { localStorage.setItem(SAVE_KEY, JSON.stringify(data)); } catch {}
378:   }
379: 
380:   readSave() {
381:     try {
382:       const raw = localStorage.getItem(SAVE_KEY);
383:       if (!raw) return null;
384:       const data = JSON.parse(raw);
385:       if (!data || data.version !== 1) return null;
386:       return data;
387:     } catch { return null; }
388:   }
389: 
390:   loadState(data) {
391:     const base = defaultState();
392:     this.state = {
393:       ...base, ...data,
394:       seeds: { ...base.seeds, ...(data.seeds || {}) },
395:       crops: { ...base.crops, ...(data.crops || {}) },
396:       stats: { ...base.stats, ...(data.stats || {}) },
397:       flags: { ...base.flags, ...(data.flags || {}) },
398:       quests: { ...(data.quests || {}) },
399:       blessing: data.blessing || 0,
400:       sprinklerCount: data.sprinklerCount || 0,
401:     };
402:     this.soundOn = this.state.soundOn !== false;
403:     this.world.setWeather(this.state.weather === 'rain' ? 'rain' : 'clear');
404:     this.world.day = this.state.day;
405:     this.world.newDay(this.state.day);
406:     for (let i = 0; i < (data.plots?.length || 0); i++) {
407:       const pd = data.plots[i];
408:       const p = this.world.plots[i];
409:       if (!pd || !p) continue;
410:       p.tilled = !!pd.tilled;
411:       p.watered = !!pd.watered;
412:       if (pd.crop && CROPS[pd.crop.type]) {
413:         p.crop = { type: pd.crop.type, grown: pd.crop.grown || 0, growDays: CROPS[pd.crop.type].grow, watered: p.watered };
414:       } else p.crop = null;
415:       this.world.refreshPlot(p);
416:     }
417:     for (let i = 0; i < this.state.sprinklerCount; i++) this.world.addSprinkler(i);
418:   }
419: 
420:   // ---------------- loop ----------------
421:   loop() {
422:     requestAnimationFrame(this.loop);
423:     let dt = this.clock.getDelta();
424:     if (dt > 0.06) dt = 0.06;
425:     this.update(dt);
426:     this.composer.render();
427:   }
428: 
429:   update(dt) {
430:     this.frames++;
431:     this.fpsAccum += dt;
432:     if (this.fpsAccum > 2) {
433:       const fps = this.frames / this.fpsAccum;
434:       if (fps < 26 && !this.lowFps) {
435:         this.lowFps = true;
436:         this.renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 1.1));
437:         this.bloom.enabled = false;
438:       }
439:       this.fpsAccum = 0; this.frames = 0;
440:     }
441: 
442:     const playing = this.mode === 'play' && !this.paused && !this.transitioning;
443:     if (this.mode === 'play' && playing) {
444:       this.state.hours += dt * 0.042;
445:       if (this.state.hours >= 24) {
446:         this.state.hours = 24;
447:         this.sleep(true);
448:       }
449:       this.updateMovement(dt);
450:       this.updateTarget();
451:       this.updateActionsUI();
452:       this.invuln = Math.max(0, this.invuln - dt);
453:       if (this.shake > 0) this.shake = Math.max(0, this.shake - dt * 2.2);
454:       this.stepAccum -= dt;
455:       if (this.player.moving && this.stepAccum <= 0) {
456:         this.stepAccum = 0.36;
457:         this.audio.sfx('step');
458:       }
459:     } else {
460:       this.player.moving = false;
461:       this.player.update(dt, false, 0, this.state.hours);
462:       this.player.faceTowards(this.player.pos.x + Math.sin(this.player.facing), this.player.pos.z + Math.cos(this.player.facing), 1);
463:     }
464: 
465:     this.player.update(dt, this.player.moving, 4.4, this.state.hours);
466:     this.slimes.update(playing ? dt : 0, this.player.pos, this);
467:     this.particles.update(dt);
468:     this.world.update(dt, this.state.hours, this.state.weather, this.player.pos);
469:     this.updateCamera(dt, false);
470: 
471:     if (playing) {
472:       this.autosaveAccum = (this.autosaveAccum || 0) + dt;
473:       if (this.autosaveAccum > 20) { this.autosaveAccum = 0; this.save(); }
474:     }
475:     this.uiAccum += dt;
476:     if (this.uiAccum > 0.12) {
477:       this.uiAccum = 0;
478:       if (this.mode === 'play') this.ui.update(this.state);
479:     }
480:     this.ambientAccum += dt;
481:     if (this.ambientAccum > 1) {
482:       this.ambientAccum = 0;
483:       if (this.mode === 'play') this.audio.updateAmbient(this.state.hours, this.state.hours > 19 || this.state.hours < 6);
484:     }
485: 
486:     if (playing) {
487:       if (!this.state.flags.tutTilled && this.state.hours > 7.4) {
488:         // no-op ambient hint handled contextually
489:       }
490:       if (this.state.hours > 19.5 && !this.state.flags.nightHint) {
491:         this.state.flags.nightHint = true;
492:         this.ui.showHint('Dusk falls. Slimes grow bold — or sleep at the cottage.', 5000);
493:       }
494:       if (this.state.hours > 23.2 && !this.state.flags.midnightHint) {
