584:   // ---------------- interaction targeting ----------------
585:   updateTarget() {
586:     const feet = this.world.plotAtWorld(this.player.pos.x, this.player.pos.z);
587:     const fwd = this.player.forward();
588:     const ahead = this.world.plotAtWorld(this.player.pos.x + fwd.x * 1.15, this.player.pos.z + fwd.z * 1.15);
589:     const plot = feet || ahead;
590:     let best = null;
591:     if (plot) {
592:       best = { kind: 'plot', plot, dist: 0, label: '', icon: '', enabled: true, prompt: '' };
593:       this.world.setTargetPlot(plot);
594:     } else {
595:       this.world.setTargetPlot(null);
596:     }
597: 
598:     const px = this.player.pos.x, pz = this.player.pos.z;
599:     const cands = [];
600:     const addCand = (kind, x, z, range, label, icon, prompt) => {
601:       const d = Math.hypot(px - x, pz - z);
602:       if (d < range) cands.push({ kind, x, z, dist: d, label, icon, prompt, enabled: true });
603:     };
604:     addCand('wizard', LAYOUT.wizard.x, LAYOUT.wizard.z, 3.0, 'Talk', '💬', 'Talk to Zephyr');
605:     addCand('tower', LAYOUT.towerDoor.x, LAYOUT.towerDoor.z, 2.9, 'Shop', '🛒', "Enter Zephyr's shop");
606:     addCand('dryad', LAYOUT.dryad.x, LAYOUT.dryad.z, 2.9, 'Talk', '💬', 'Talk to Nissa');
607:     addCand('home', LAYOUT.homeDoor.x, LAYOUT.homeDoor.z, 3.0, 'Sleep', '🌙', 'Sleep until dawn');
608:     addCand('shrine', LAYOUT.shrine.x, LAYOUT.shrine.z, 3.5, 'Moonwell', '✦', 'Touch the Moonwell');
609: 
610:     let treeBest = null, td = 2.8;
611:     for (const t of this.world.trees) {
612:       if (!t.active) continue;
613:       const d = Math.hypot(px - t.x, pz - t.z) - t.scale * 0.35;
614:       if (d < td) { td = d; treeBest = t; }
615:     }
616:     if (treeBest) cands.push({ kind: 'tree', dist: td, label: 'Chop', icon: '🪓', prompt: 'Chop the tree', tree: treeBest, enabled: true });
617:     let rockBest = null, rd = 2.7;
618:     for (const r of this.world.rocks) {
619:       if (!r.active) continue;
620:       const d = Math.hypot(px - r.x, pz - r.z) - r.scale * 0.4;
621:       if (d < rd) { rd = d; rockBest = r; }
622:     }
623:     if (rockBest) cands.push({ kind: 'rock', dist: rd, label: 'Mine', icon: '⛏', prompt: 'Mine the stone', rock: rockBest, enabled: true });
624: 
625:     if (!plot && cands.length) {
626:       cands.sort((a, b) => a.dist - b.dist);
627:       best = cands[0];
628:     }
629:     if (best && best.kind === 'plot') {
630:       this.describePlot(best);
631:     }
632:     this.target = best;
633:   }
