729:       this.audio.sfx('till');
730:       if (!this.state.flags.tutTilled) {
731:         this.state.flags.tutTilled = true;
732:         setTimeout(() => this.ui.showHint('Pick a seed from the hotbar, then press Use to plant it.', 6000), 500);
733:       }
734:       this.save();
735:       return;
736:     }
737:     if (!p.crop) {
738:       const type = this.state.selectedSeed;
739:       const c = CROPS[type];
740:       if ((this.state.seeds[type] || 0) <= 0) {
741:         this.ui.toast(`No ${c.name} seeds. Buy more from Zephyr.`, '', '🌱');
742:         this.audio.sfx('error');
743:         return;
744:       }
745:       if (!this.spendEnergy(1)) return;
746:       this.state.seeds[type]--;
747:       const raining = this.state.weather === 'rain';
748:       p.crop = { type, grown: 0, growDays: c.grow, watered: raining };
749:       p.watered = raining;
750:       this.world.refreshPlot(p);
751:       this.particles.emit(new THREE.Vector3(p.x, 0.3, p.z), '#a8e08a', 10, 1.8, 2.2);
752:       this.ui.float(`🌱 ${c.name}`, new THREE.Vector3(p.x, 1.0, p.z), 'heal');
753:       this.audio.sfx('plant');
754:       this.state.stats.planted++;
755:       if (!this.state.flags.tutPlanted) {
756:         this.state.flags.tutPlanted = true;
757:         setTimeout(() => this.ui.showHint('Now water it. Crops only grow overnight when watered.', 6000), 500);
758:       }
759:       this.checkQuests();
760:       this.save();
761:       return;
762:     }
763:     const c = CROPS[p.crop.type];
764:     if (p.crop.grown >= p.crop.growDays) {
765:       const type = p.crop.type;
766:       this.state.crops[type] = (this.state.crops[type] || 0) + 1;
767:       this.state.stats.harvested++;
768:       p.crop = null;
769:       p.watered = false;
770:       this.world.refreshPlot(p);
771:       this.particles.emit(new THREE.Vector3(p.x, 0.8, p.z), c.color, 22, 3.0, 3.2);
772:       this.particles.emit(new THREE.Vector3(p.x, 0.6, p.z), '#ffe9a0', 10, 2.0, 2.6);
773:       this.ui.float(`+1 ${c.name}`, new THREE.Vector3(p.x, 1.4, p.z), 'gold');
774:       this.audio.sfx('harvest');
775:       this.ui.toast(`${c.name} harvested! Sell it at Zephyr's tower for ${c.sell} ◈.`, 'quest', '🌾');
776:       this.checkQuests();
777:       this.save();
778:       return;
779:     }
780:     if (!p.crop.watered) {
781:       if (!this.spendEnergy(1)) return;
782:       p.crop.watered = true;
783:       p.watered = true;
784:       this.world.refreshPlot(p);
785:       this.state.stats.wateredToday++;
786:       this.particles.emit(new THREE.Vector3(p.x, 0.4, p.z), '#9fe6ff', 14, 1.8, 2.4);
787:       this.ui.float('💧', new THREE.Vector3(p.x, 0.9, p.z), 'ess');
