352:     for (const sp of this.world.sprinklers) this.scene.remove(sp.group);
353:     this.world.sprinklers.length = 0;
354:     this.world.newDay(1);
355:     this.world.day = 1;
356:     this.world.setWeather('clear');
357:     this.slimes.resetDay(1);
358:     this.invuln = 0;
359:     this.transitioning = false;
360:     this.sleeping = false;
