404:     this.world.day = this.state.day;
405:     this.world.newDay(this.state.day);
406:     for (let i = 0; i < (data.plots?.length || 0); i++) {
407:       const pd = data.plots[i];
408:       const p = this.world.plots[i];
409:       if (!pd || !p) continue;
