420:   // ---------------- loop ----------------
421:   loop() {
422:     requestAnimationFrame(this.loop);
423:     let dt = this.clock.getDelta();
424:     if (dt > 0.06) dt = 0.06;
425:     this.update(dt);
426:     this.composer.render();
