924:   advanceDay() {
925:     const s = this.state;
926:     let grown = 0;
927:     for (const p of this.world.plots) {
928:       if (!p.crop) { p.watered = false; continue; }
929:       if (p.crop.watered) {
930:         if (p.crop.grown < p.crop.growDays) {
931:           p.crop.grown++;
932:           grown++;
933:         }
934:       }
935:       p.crop.watered = false;
936:       p.watered = false;
937:     }
938:     s.day++;
939:     s.hours = 6.15;
940:     s.season = 'Spring';
941:     let rain = Math.random() < 0.34;
942:     if (s.flags.forceRain) { rain = true; s.flags.forceRain = false; }
943:     s.weather = rain ? 'rain' : 'clear';
944:     if (rain) {
945:       for (const p of this.world.plots) {
946:         if (p.crop) { p.crop.watered = true; p.watered = true; }
947:         else if (p.tilled) p.watered = true;
948:       }
949:     }
950:     // sprinklers
951:     let sprinklered = 0;
952:     for (const sp of this.world.sprinklers) {
953:       for (const p of this.world.plots) {
954:         if (!p.crop) continue;
955:         if (Math.hypot(p.x - sp.x, p.z - sp.z) < 3.1) {
956:           p.crop.watered = true;
957:           p.watered = true;
958:           sprinklered++;
959:         }
960:       }
961:     }
962:     s.energy = s.maxEnergy;
963:     s.health = s.maxHealth;
964:     const earned = s.stats.dayEarned || 0;
965:     s.stats.dayEarned = 0;
966:     s.stats.wateredToday = 0;
967:     this.world.setWeather(s.weather);
968:     this.world.newDay(s.day);
969:     this.world.day = s.day;
970:     this.slimes.resetDay(s.day);
971:     for (const p of this.world.plots) this.world.refreshPlot(p);
972:     this.invuln = 0;
973:     this.shake = 0;
974:     const flavors = rain
975:       ? ['Rain taps the roof like tiny knuckles. The fields drink deep.', 'The vale smells of wet earth and green things. A good day to stay in.', 'Mist curls between the fence posts. The crops are already grateful.']
976:       : ['Birds stitch the morning together. The vale is quiet and kind.', 'Sunlight spills over the fence like warm honey.', 'Somewhere in the Whisperwood, a slime yawns. The farm waits.', 'The Moonwell hums softly. Another day to grow something impossible.'];
977:     this.save();
978:     return {
979:       day: s.day, season: s.season, weather: s.weather, crops: grown,
980:       earned, maxEnergy: s.maxEnergy, rain, sprinklers: this.world.sprinklers.length,
981:       flavor: flavors[(Math.random() * flavors.length) | 0],
982:     };
983:   }
