992:     const fwd = this.player.forward();
993:     const hitList = [];
994:     for (const sl of this.slimes.slimes) {
995:       if (!sl.alive) continue;
996:       const dx = sl.x - this.player.pos.x;
997:       const dz = sl.z - this.player.pos.z;
998:       const d = Math.hypot(dx, dz);
999:       if (d > 3.0) continue;
1000:       const dot = (dx / Math.max(d, 0.001)) * fwd.x + (dz / Math.max(d, 0.001)) * fwd.z;
1001:       if (dot < -0.15) continue;
1002:       hitList.push(sl);
1003:     }
1004:     if (!hitList.length) {
1005:       setTimeout(() => this.audio.sfx('attack'), 50);
1006:       return;
1007:     }
1008:     for (const sl of hitList) {
1009:       const dirX = (sl.x - this.player.pos.x), dirZ = (sl.z - this.player.pos.z);
1010:       const dl = Math.hypot(dirX, dirZ) || 1;
1011:       const dead = this.slimes.hit(sl, dirX / dl, dirZ / dl);
1012:       this.particles.emit(new THREE.Vector3(sl.x, 0.7, sl.z), '#c7ffd7', 12, 2.6, 3);
1013:       this.audio.sfx('hit');
1014:       this.shake = 0.12;
1015:       if (dead) {
1016:         this.slimes.kill(sl);
1017:         this.state.stats.slimes++;
1018:         const ess = 1 + (Math.random() < 0.4 ? 1 : 0);
1019:         this.state.essence += ess;
1020:         this.state.gold += 2;
1021:         this.state.stats.dayEarned += 2;
1022:         this.particles.emit(new THREE.Vector3(sl.x, 0.8, sl.z), '#7fe4ff', 24, 3.2, 3.2);
