1024:         this.ui.float(`+${ess} ✦ · +2 ◈`, new THREE.Vector3(sl.x, 1.6, sl.z), 'ess');
1025:         this.audio.sfx('slime');
1026:         this.checkQuests();
1027:         this.save();
1028:       } else {
1029:         this.ui.float('-1', new THREE.Vector3(sl.x, 1.2, sl.z), 'dmg');
1030:       }
1031:     }
