575:   updateCropVisual(plot) {
576:     if (!plot.crop) {
577:       if (plot.visual) {
578:         this.scene.remove(plot.visual);
579:         plot.visual = null;
580:       }
581:       return;
582:     }
583:     if (!plot.visual) {
584:       const g = new THREE.Group();
585:       g.position.set(plot.x, 0.1, plot.z);
586:       const plant = new THREE.Mesh(this.cropPlantGeo, this.cropPlantMat);
587:       plant.castShadow = true;
588:       const fruit = new THREE.Mesh(this.cropFruitGeo, this.cropMats[plot.crop.type]);
589:       fruit.position.y = 1.1;
