1061:           vec2 p = vWorld.xz;
1062:           float w1 = sin(p.x*1.3 + uTime*0.9) * cos(p.y*1.1 - uTime*0.7);
1063:           float w2 = sin((p.x+p.y)*2.1 - uTime*1.4) * 0.5;
