1067:           float edge = smoothstep(0.0, 1.0, vUv.y);
1068:           vec3 col = mix(shallow, deep, 0.55 + ripple*0.18);
1069:           col += vec3(0.25,0.5,0.45) * pow(max(0.0,ripple),3.0) * 0.6;
1070:           float sparkle = smoothstep(0.93, 1.0, sin(p.x*6.0 + uTime*2.0)*sin(p.y*5.0 - uTime*1.6));
1071:           col += vec3(0.8,0.95,0.9) * sparkle * 0.5;
1072:           gl_FragColor = vec4(col, 0.88);
1073:           #include <tonemapping_fragment>
1074:           #include <colorspace_fragment>
1075:         }
1076:       `,
1077:     });
