428: 
429:   update(dt) {
430:     this.frames++;
431:     this.fpsAccum += dt;
432:     if (this.fpsAccum > 2) {
433:       const fps = this.frames / this.fpsAccum;
434:       if (fps < 26 && !this.lowFps) {
435:         this.lowFps = true;
436:         this.renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 1.1));
437:         this.bloom.enabled = false;
438:       }
439:       this.fpsAccum = 0; this.frames = 0;
440:     }
441: 
442:     const playing = this.mode === 'play' && !this.paused && !this.transitioning;
443:     if (this.mode === 'play' && playing) {
444:       this.state.hours += dt * 0.042;
445:       if (this.state.hours >= 24) {
446:         this.state.hours = 24;
447:         this.sleep(true);
448:       }
449:       this.updateMovement(dt);
450:       this.updateTarget();
451:       this.updateActionsUI();
452:       this.invuln = Math.max(0, this.invuln - dt);
453:       if (this.shake > 0) this.shake = Math.max(0, this.shake - dt * 2.2);
454:       this.stepAccum -= dt;
455:       if (this.player.moving && this.stepAccum <= 0) {
456:         this.stepAccum = 0.36;
457:         this.audio.sfx('step');
458:       }
459:     } else {
460:       this.player.moving = false;
461:       this.player.update(dt, false, 0, this.state.hours);
462:       this.player.faceTowards(this.player.pos.x + Math.sin(this.player.facing), this.player.pos.z + Math.cos(this.player.facing), 1);
463:     }
464: 
465:     this.player.update(dt, this.player.moving, 4.4, this.state.hours);
466:     this.slimes.update(playing ? dt : 0, this.player.pos, this);
467:     this.particles.update(dt);
468:     this.world.update(dt, this.state.hours, this.state.weather, this.player.pos);
469:     this.updateCamera(dt, false);
470: 
471:     if (playing) {
472:       this.autosaveAccum = (this.autosaveAccum || 0) + dt;
473:       if (this.autosaveAccum > 20) { this.autosaveAccum = 0; this.save(); }
474:     }
475:     this.uiAccum += dt;
476:     if (this.uiAccum > 0.12) {
477:       this.uiAccum = 0;
478:       if (this.mode === 'play') this.ui.update(this.state);
479:     }
480:     this.ambientAccum += dt;
481:     if (this.ambientAccum > 1) {
482:       this.ambientAccum = 0;
483:       if (this.mode === 'play') this.audio.updateAmbient(this.state.hours, this.state.hours > 19 || this.state.hours < 6);
484:     }
485: 
486:     if (playing) {
487:       if (!this.state.flags.tutTilled && this.state.hours > 7.4) {
488:         // no-op ambient hint handled contextually
489:       }
490:       if (this.state.hours > 19.5 && !this.state.flags.nightHint) {
491:         this.state.flags.nightHint = true;
492:         this.ui.showHint('Dusk falls. Slimes grow bold — or sleep at the cottage.', 5000);
493:       }
494:       if (this.state.hours > 23.2 && !this.state.flags.midnightHint) {
495:         this.state.flags.midnightHint = true;
496:         this.ui.showHint('Midnight approaches. Head home to sleep.', 5000);
497:       }
498:     }
499:   }
