431:   buildFarm() {
432:     const { cols, rows, tile, ox, oz } = FARM;
433:     const soilGeo = new THREE.BoxGeometry(tile * 0.94, 0.16, tile * 0.94);
434:     const soilMat = stdMat({ color: 0xffffff, roughness: 1 });
435:     this.soilMesh = new THREE.InstancedMesh(soilGeo, soilMat, cols * rows);
436:     this.soilMesh.receiveShadow = true;
437:     this.soilMesh.frustumCulled = false;
438:     const zero = new THREE.Matrix4().makeScale(0.0001, 0.0001, 0.0001);
439:     for (let i = 0; i < cols * rows; i++) {
440:       this.soilMesh.setMatrixAt(i, zero);
441:       this.soilMesh.setColorAt(i, new THREE.Color('#6b4a2e'));
442:     }
443:     this.soilMesh.instanceMatrix.needsUpdate = true;
444:     if (this.soilMesh.instanceColor) this.soilMesh.instanceColor.needsUpdate = true;
445:     this.scene.add(this.soilMesh);
446: 
447:     this.plots = [];
448:     for (let j = 0; j < rows; j++) {
449:       for (let i = 0; i < cols; i++) {
450:         const x = ox + (i + 0.5) * tile;
451:         const z = oz + (j + 0.5) * tile;
452:         this.plots.push({
453:           index: j * cols + i, i, j, x, z,
454:           tilled: false, watered: false, crop: null,
455:           visual: null,
456:         });
457:         this.plotStates.push({ tilled: false });
458:       }
459:     }
460: 
461:     // crop geometries
462:     const stem = new THREE.CylinderGeometry(0.05, 0.075, 0.92, 4, 1);
463:     stem.translate(0, 0.46, 0);
464:     const leafParts = [{ geo: stem, color: '#4c9a4a' }];
465:     for (let i = 0; i < 4; i++) {
466:       const leaf = new THREE.ConeGeometry(0.2, 0.58, 4, 1);
467:       leaf.scale(1, 0.5, 1);
468:       leaf.rotateZ(Math.PI / 2.4);
469:       leaf.rotateY((i / 4) * Math.PI * 2);
470:       leaf.translate(Math.cos((i / 4) * Math.PI * 2) * 0.19, 0.32 + i * 0.16, Math.sin((i / 4) * Math.PI * 2) * 0.19);
471:       leafParts.push({ geo: leaf, color: i % 2 ? '#5ea94e' : '#438a43' });
472:     }
473:     this.cropPlantGeo = mergeColored(leafParts);
474:     this.cropPlantMat = vcMat();
475: 
476:     this.cropFruitGeo = new THREE.IcosahedronGeometry(0.23, 0);
477:     this.cropMats = {
478:       moon: stdMat({ color: '#d8f3ff', emissive: '#7fd4ff', emissiveIntensity: 1.7, roughness: 0.35 }),
479:       sun: stdMat({ color: '#ffd166', emissive: '#ff9a20', emissiveIntensity: 1.5, roughness: 0.4 }),
480:       star: stdMat({ color: '#ffe9a3', emissive: '#ffcf4d', emissiveIntensity: 1.8, roughness: 0.3 }),
481:     };
482: 
483:     // target highlight
484:     const hlGeo = new THREE.PlaneGeometry(tile * 0.98, tile * 0.98);
485:     hlGeo.rotateX(-Math.PI / 2);
486:     this.highlight = new THREE.Group();
487:     const fill = new THREE.Mesh(hlGeo, new THREE.MeshBasicMaterial({
488:       color: 0xffe4a1, transparent: true, opacity: 0.17, depthWrite: false, toneMapped: false,
489:     }));
490:     fill.position.y = 0.13;
491:     const edge = new THREE.LineSegments(
492:       new THREE.EdgesGeometry(hlGeo),
493:       new THREE.LineBasicMaterial({ color: 0xffe6a8, transparent: true, opacity: 0.85, toneMapped: false })
494:     );
495:     edge.position.y = 0.14;
496:     this.highlight.add(fill, edge);
497:     this.highlight.visible = false;
498:     this.scene.add(this.highlight);
499: 
500:     // faint field grid so the plot reads as a tended field before tilling
501:     const gridPts = [];
502:     const gx0 = ox, gz0 = oz, gx1 = ox + cols * tile, gz1 = oz + rows * tile;
503:     const gy = 0.045;
504:     for (let i = 0; i <= cols; i++) {
505:       const gx = gx0 + i * tile;
506:       gridPts.push(gx, gy, gz0, gx, gy, gz1);
507:     }
508:     for (let j = 0; j <= rows; j++) {
509:       const gz = gz0 + j * tile;
510:       gridPts.push(gx0, gy, gz, gx1, gy, gz);
511:     }
512:     const gg = new THREE.BufferGeometry();
513:     gg.setAttribute('position', new THREE.Float32BufferAttribute(gridPts, 3));
514:     const grid = new THREE.LineSegments(gg, new THREE.LineBasicMaterial({
515:       color: 0x466335, transparent: true, opacity: 0.42, depthWrite: false,
516:     }));
517:     this.scene.add(grid);
518: 
519:     // corner stakes
520:     const stakeMat = stdMat({ color: '#7b5a36' });
521:     for (const [sx, sz] of [[gx0, gz0], [gx1, gz0], [gx0, gz1], [gx1, gz1]]) {
522:       const st = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.08, 0.55, 5), stakeMat);
523:       st.position.set(sx, 0.22, sz);
524:       st.castShadow = true;
525:       this.scene.add(st);
526:     }
527: 
528:     this.buildFarmProps(gx0, gz0, gx1, gz1);
529: 
530:     // scarecrow
531:     this.buildScarecrow(7.4, -7.9);
532:   }
