547:   setTargetPlot(plot) {
548:     if (!plot || plot.index === this.targetPlot) {
549:       if (!plot) {
550:         this.highlight.visible = false;
551:         this.targetPlot = -1;
552:       }
553:       return;
554:     }
555:     this.targetPlot = plot.index;
556:     this.highlight.visible = true;
557:     this.highlight.position.set(plot.x, 0, plot.z);
558:   }
