611:   // =========================================================== fence
612:   buildFence() {
613:     const H = LAYOUT.fence;
614:     const parts = [];
615:     const postGeo = () => {
616:       const g = new THREE.BoxGeometry(0.18, 1.06, 0.18);
617:       g.translate(0, 0.53, 0);
618:       return g;
619:     };
620:     const rail = (x1, z1, x2, z2, y) => {
621:       const dx = x2 - x1, dz = z2 - z1;
622:       const len = Math.hypot(dx, dz);
623:       const g = new THREE.BoxGeometry(len, 0.11, 0.09);
624:       g.rotateY(-Math.atan2(dz, dx));
625:       g.translate((x1 + x2) / 2, y, (z1 + z2) / 2);
626:       return g;
627:     };
628:     const addRun = (x1, z1, x2, z2) => {
629:       const len = Math.hypot(x2 - x1, z2 - z1);
630:       const n = Math.max(1, Math.round(len / 1.55));
631:       for (let i = 0; i <= n; i++) {
632:         const t = i / n;
633:         const px = lerp(x1, x2, t), pz = lerp(z1, z2, t);
634:         const y = this.height(px, pz);
635:         if (i > 0) {
636:           parts.push({ geo: xf(postGeo(), px, y - 0.05, pz), color: '#8a6542', jitter: 0.05 });
637:         }
638:       }
639:       const segs = 4;
640:       for (let s = 0; s < segs; s++) {
641:         const t0 = s / segs, t1 = (s + 1) / segs;
642:         const ax = lerp(x1, x2, t0), az = lerp(z1, z2, t0);
643:         const bx = lerp(x1, x2, t1), bz = lerp(z1, z2, t1);
644:         const yA = this.height(ax, az), yB = this.height(bx, bz);
645:         parts.push({ geo: xf(rail(ax, az, bx, bz, 0.42 + (yA + yB) / 2), 0, 0, 0), color: '#9b7550', jitter: 0.04 });
646:         parts.push({ geo: xf(rail(ax, az, bx, bz, 0.8 + (yA + yB) / 2), 0, 0, 0), color: '#8f6a47', jitter: 0.04 });
647:       }
648:       this.segments.push({ ax: x1, az: z1, bx: x2, bz: z2, r: 0.22 });
649:     };
650:     addRun(-H, -H, -H, H);
651:     addRun(H, -H, H, H);
652:     addRun(-H, -H, -1.4, -H);
653:     addRun(1.4, -H, H, -H);
654:     addRun(-H, H, -1.4, H);
655:     addRun(1.4, H, H, H);
656:     // corner posts
657:     for (const [x, z] of [[-H, -H], [H, -H], [-H, H], [H, H], [-1.4, -H], [1.4, -H], [-1.4, H], [1.4, H]]) {
658:       parts.push({ geo: xf(postGeo(), x, this.height(x, z) - 0.02, z, 0, 0, 0, 1.35), color: '#755435', jitter: 0.04 });
659:     }
660:     const mesh = new THREE.Mesh(mergeColored(parts), vcMat());
661:     mesh.castShadow = true; mesh.receiveShadow = true;
662:     this.scene.add(mesh);
663: 
664:     // gate lanterns
665:     for (const [x, z] of [[-1.6, H], [1.6, H], [-1.6, -H], [1.6, -H]]) {
666:       const y = this.height(x, z);
667:       const post = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.12, 1.9, 6), stdMat({ color: '#6a4c30' }));
668:       post.position.set(x, y + 0.95, z);
669:       const lamp = glowSprite('#ffc978', 1.05, 0.32);
670:       lamp.position.set(x, y + 2.0, z);
671:       const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.15, 8, 6), new THREE.MeshStandardMaterial({ color: '#ffd49a', emissive: '#ffb45e', emissiveIntensity: 0.12 }));
672:       bulb.position.copy(lamp.position);
673:       this.scene.add(post, lamp, bulb);
674:       this.gateLights.push({ lamp, bulb });
675:     }
676:   }
