1128:   buildNature() {
1129:     const broadParts = [
1130:       { geo: xf(new THREE.CylinderGeometry(0.16, 0.26, 2.0, 6), 0, 1.0, 0), color: '#6d5138' },
1131:     ];
1132:     for (const [px, py, pz, r, c] of [
1133:       [0, 2.7, 0, 1.55, TREE_GREENS[0]],
1134:       [0.8, 2.3, 0.5, 1.05, TREE_GREENS[1]],
1135:       [-0.85, 2.4, 0.25, 1.0, TREE_GREENS[2]],
1136:       [0.1, 3.4, -0.4, 1.0, TREE_GREENS[3]],
1137:       [0.5, 3.1, 0.7, 0.8, TREE_GREENS[1]],
1138:     ]) {
1139:       const geo = new THREE.IcosahedronGeometry(r, 0);
1140:       geo.scale(1, 0.86, 1);
1141:       geo.translate(px, py, pz);
1142:       broadParts.push({ geo, color: c, jitter: 0.06 });
