1144:     const broadGeo = mergeColored(broadParts);
1145:     const broadMat = vcMat();
1146: 
1147:     const pineParts = [{ geo: xf(new THREE.CylinderGeometry(0.14, 0.24, 1.6, 6), 0, 0.8, 0), color: '#5a4632' }];
1148:     for (let i = 0; i < 4; i++) {
