1150:       const cone = new THREE.ConeGeometry(r, 1.85, 7, 1);
1151:       cone.translate(0, 1.5 + i * 0.95, 0);
1152:       pineParts.push({ geo: cone, color: PINE_GREENS[i % 3], jitter: 0.05 });
1153:     }
1154:     const pineGeo = mergeColored(pineParts);
1155: 
1156:     const magicParts = [
1157:       { geo: xf(new THREE.CylinderGeometry(0.14, 0.3, 2.2, 6), 0, 1.1, 0), color: '#b9a4c9' },
1158:     ];
1159:     for (const [px, py, pz, r, c] of [
1160:       [0, 2.9, 0, 1.6, '#8e6cc0'], [0.9, 2.3, 0.3, 1.1, '#c477c9'],
1161:       [-0.9, 2.4, -0.2, 1.05, '#7957ad'], [0.1, 3.7, 0.2, 1.0, '#d490d8'],
1162:     ]) {
1163:       const geo = new THREE.IcosahedronGeometry(r, 0);
1164:       geo.translate(px, py, pz);
1165:       magicParts.push({ geo, color: c, jitter: 0.05 });
1166:     }
1167:     const magicGeo = mergeColored(magicParts);
1168: 
1169:     const placements = { broad: [], pine: [], magic: [] };
1170:     const pts = [];
1171:     let guard = 0;
1172:     while (pts.length < 150 && guard++ < 5000) {
1173:       const a = rand(0, Math.PI * 2);
1174:       const rr = rand(13, 58);
1175:       const x = Math.cos(a) * rr, z = Math.sin(a) * rr;
1176:       if (Math.abs(x) < 11.5 && Math.abs(z) < 11.5) continue;
1177:       if (Math.hypot(x - LAYOUT.home.x, z - LAYOUT.home.z) < 9) continue;
1178:       if (Math.hypot(x - LAYOUT.tower.x, z - LAYOUT.tower.z) < 7.5) continue;
1179:       if (Math.hypot(x - LAYOUT.shrine.x, z - LAYOUT.shrine.z) < 7.4) continue;
1180:       if (Math.hypot(x - LAYOUT.pond.x, z - LAYOUT.pond.z) < 9.5) continue;
1181:       if (Math.hypot(x - LAYOUT.spawn.x, z - LAYOUT.spawn.z) < 5) continue;
1182:       if (Math.hypot(x + 14, z - 26) < 12) continue;
1183:       if (x > -14 && x < 18 && z > 10.5 && z < 31) continue;
1184:       if (this.nearPath(x, z, 3.1)) continue;
1185:       if (this.height(x, z) < -0.35) continue;
1186:       if (pts.some((p) => Math.hypot(p.x - x, p.z - z) < 3.2)) continue;
1187:       pts.push({ x, z });
1188:     }
1189: 
1190:     for (const p of pts) {
1191:       const dShrine = Math.hypot(p.x - LAYOUT.shrine.x, p.z - LAYOUT.shrine.z);
1192:       const west = p.x < -13, north = p.z < -15, east = p.x > 20;
1193:       let kind = 'broad';
1194:       const r = Math.random();
1195:       if (dShrine < 13 && r < 0.55) kind = 'magic';
1196:       else if ((west || north || east) && r < 0.55) kind = 'pine';
1197:       else if (r < 0.32) kind = 'pine';
1198:       else if (r < 0.42) kind = 'magic';
1199:       placements[kind].push(p);
1200:     }
1201: 
1202:     const makeTreeInstances = (geo, mat, list, kind) => {
1203:       const mesh = new THREE.InstancedMesh(geo, mat, Math.max(list.length, 1));
1204:       mesh.castShadow = true;
1205:       mesh.receiveShadow = true;
1206:       mesh.count = list.length;
1207:       const m = new THREE.Matrix4(), q = new THREE.Quaternion(), s = new THREE.Vector3(), p = new THREE.Vector3();
1208:       list.forEach((pt, idx) => {
1209:         const sc = rand(0.85, 1.35);
1210:         p.set(pt.x, this.height(pt.x, pt.z) - 0.05, pt.z);
1211:         q.setFromEuler(new THREE.Euler(0, rand(0, Math.PI * 2), 0));
1212:         s.set(sc, sc * rand(0.9, 1.15), sc);
1213:         m.compose(p, q, s);
1214:         mesh.setMatrixAt(idx, m);
1215:         const tree = {
1216:           kind, x: pt.x, z: pt.z, scale: sc, active: true, hits: 3, maxHits: 3,
1217:           respawnDay: 0, mesh, idx, base: m.clone(), ref: null,
1218:         };
1219:         tree.ref = tree;
1220:         this.trees.push(tree);
1221:         this.colliders.push({ x: pt.x, z: pt.z, r: 0.55 * sc, tree });
1222:       });
1223:       mesh.instanceMatrix.needsUpdate = true;
1224:       this.scene.add(mesh);
