29:       el.addEventListener('click', (e) => { e.preventDefault(); this.game.audio.init(); this.game.audio.sfx('click'); fn(e); });
30:     };
31:     tap('btn-menu', () => this.game.openMenu());
32:     tap('btn-action', () => this.game.doAction());
33:     tap('btn-attack', () => this.game.doAttack());
