39:     // joystick
40:     const joy = $('joystick');
41:     const stick = $('stick');
42:     let active = false, pid = null;
43:     const center = () => {
44:       const r = joy.getBoundingClientRect();
45:       return { x: r.left + r.width / 2, y: r.top + r.height / 2, rad: r.width * 0.33 };
46:     };
47:     const move = (e) => {
48:       if (!active || e.pointerId !== pid) return;
49:       const c = center();
50:       let dx = e.clientX - c.x, dy = e.clientY - c.y;
51:       const len = Math.hypot(dx, dy);
52:       const max = c.rad;
53:       if (len > max) { dx = (dx / len) * max; dy = (dy / len) * max; }
54:       stick.style.transform = `translate(${dx}px, ${dy}px)`;
55:       this.game.joystick.x = dx / max;
56:       this.game.joystick.y = dy / max;
57:     };
58:     joy.addEventListener('pointerdown', (e) => {
59:       active = true; pid = e.pointerId;
60:       joy.setPointerCapture(e.pointerId);
61:       this.game.audio.init();
62:       move(e);
63:     });
64:     joy.addEventListener('pointermove', move);
65:     const end = (e) => {
66:       if (e.pointerId !== pid) return;
67:       active = false; pid = null;
68:       stick.style.transform = 'translate(0px, 0px)';
69:       this.game.joystick.x = 0; this.game.joystick.y = 0;
70:     };
71:     joy.addEventListener('pointerup', end);
72:     joy.addEventListener('pointercancel', end);
73:     joy.addEventListener('lostpointercapture', end);
74: 
75:     // modal close
76:     this.modal.addEventListener('click', (e) => {
77:       if (e.target === this.modal && this.modalKind !== 'win' && this.modalKind !== 'summary') this.closeModal();
78:     });
79:     this.modal.addEventListener('click', (e) => {
80:       const close = e.target.closest('[data-close]');
81:       if (close) this.closeModal();
82:     });
83:     this.modal.addEventListener('click', (e) => {
