386:     const nightTop = new THREE.Color('#071021');
387:     const nightHor = new THREE.Color('#182b46');
388:     const nightBot = new THREE.Color('#0d1827');
389:     const duskTop = new THREE.Color('#4f4a80');
390:     const duskHor = new THREE.Color('#f19a68');
391:     const duskBot = new THREE.Color('#5b5260');
392:     const dayTop = new THREE.Color('#5db3e3');
393:     const dayHor = new THREE.Color('#dceef0');
394:     const dayBot = new THREE.Color('#9fb992');
395: 
396:     const top = nightTop.clone().lerp(duskTop, duskW).lerp(dayTop, dayW);
397:     const hor = nightHor.clone().lerp(duskHor, duskW).lerp(dayHor, dayW);
398:     const bot = nightBot.clone().lerp(duskBot, duskW).lerp(dayBot, dayW);
399: 
400:     this.skyMat.uniforms.top.value.copy(top);
401:     this.skyMat.uniforms.horizon.value.copy(hor);
402:     this.skyMat.uniforms.bottom.value.copy(bot);
403:     this.scene.fog.color.copy(hor).multiplyScalar(0.88);
404:     this.starMat.opacity = clamp(1 - smoothstep(-0.16, 0.12, elev), 0, 1) * 0.95;
405: 
406:     const dir = new THREE.Vector3(Math.cos(ang) * 0.92, Math.sin(ang), 0.34).normalize();
407:     this.sunSprite.position.copy(dir).multiplyScalar(270);
408:     this.moonSprite.position.copy(dir).multiplyScalar(-270);
409:     this.sunSprite.material.opacity = clamp(elev * 6, 0, 0.95);
410:     this.moonSprite.material.opacity = clamp(-elev * 5, 0, 0.85);
411:     const sunScale = 30 + (1 - clamp(elev, 0, 1)) * 16;
412:     this.sunSprite.scale.setScalar(sunScale);
413:     this.sunSprite.material.color.set(dayW > 0.4 ? 0xfff0c0 : 0xffb27a);
414: 
415:     const ldir = dir.clone().multiplyScalar(80);
416:     this.sun.position.set(ldir.x, Math.max(ldir.y, 4), ldir.z + 20);
417:     this.sun.target.position.set(0, 0, 0);
418:     this.sun.intensity = 0.12 + dayW * 2.5 + duskW * 0.9;
419:     this.sun.color.copy(new THREE.Color('#ff9d6a')).lerp(new THREE.Color('#fff2d8'), dayW);
420:     this.sun.castShadow = elev > -0.05;
421:     this.moonLight.position.copy(dir).multiplyScalar(-70);
422:     this.moonLight.intensity = (1 - dayW) * 0.42;
423:     this.hemi.intensity = 0.22 + dayW * 0.72 + duskW * 0.24;
424:     this.hemi.color.copy(new THREE.Color('#7591c7')).lerp(new THREE.Color('#cfe8ff'), dayW);
425:     this.hemi.groundColor.copy(new THREE.Color('#24301f')).lerp(new THREE.Color('#69874f'), dayW);
426: 
427:     return { elev, dayW, duskW };
428:   }
