560:   updateSoilVisual(plot) {
561:     const m = new THREE.Matrix4();
562:     if (!plot.tilled) {
563:       m.makeScale(0.0001, 0.0001, 0.0001);
564:       this.soilMesh.setMatrixAt(plot.index, m);
565:     } else {
566:       m.makeTranslation(plot.x, 0.02, plot.z);
567:       this.soilMesh.setMatrixAt(plot.index, m);
568:       const c = new THREE.Color(plot.watered ? '#67482c' : '#8a6138');
569:       this.soilMesh.setColorAt(plot.index, c);
570:     }
571:     this.soilMesh.instanceMatrix.needsUpdate = true;
572:     if (this.soilMesh.instanceColor) this.soilMesh.instanceColor.needsUpdate = true;
573:   }
574: 
575:   updateCropVisual(plot) {
576:     if (!plot.crop) {
577:       if (plot.visual) {
578:         this.scene.remove(plot.visual);
579:         plot.visual = null;
580:       }
581:       return;
582:     }
583:     if (!plot.visual) {
584:       const g = new THREE.Group();
585:       g.position.set(plot.x, 0.1, plot.z);
586:       const plant = new THREE.Mesh(this.cropPlantGeo, this.cropPlantMat);
587:       plant.castShadow = true;
588:       const fruit = new THREE.Mesh(this.cropFruitGeo, this.cropMats[plot.crop.type]);
589:       fruit.position.y = 1.1;
590:       fruit.castShadow = true;
591:       g.add(plant, fruit);
592:       this.scene.add(g);
593:       plot.visual = g;
594:       plot.plantMesh = plant;
595:       plot.fruitMesh = fruit;
596:     }
597:     const ratio = clamp(plot.crop.grown / plot.crop.growDays, 0, 1);
598:     const s = 0.5 + ratio * 0.72;
599:     plot.visual.scale.set(s, s, s);
600:     plot.visual.rotation.y = (plot.index % 7) * 0.8;
601:     const fruitScale = ratio >= 0.98 ? 1 + Math.sin(this.time * 2.4 + plot.index) * 0.08 : ratio > 0.55 ? 0.5 : 0.001;
602:     plot.fruitMesh.scale.setScalar(fruitScale);
603:     plot.fruitMesh.visible = ratio > 0.55;
604:   }
605: 
606:   refreshPlot(plot) {
607:     this.updateSoilVisual(plot);
608:     this.updateCropVisual(plot);
609:   }
