52: // ---------------- particles ----------------
53: class Particles {
54:   constructor(scene) {
55:     this.max = 260;
56:     this.pos = new Float32Array(this.max * 3);
57:     this.col = new Float32Array(this.max * 3);
58:     this.vel = new Float32Array(this.max * 3);
59:     this.life = new Float32Array(this.max);
60:     this.maxLife = new Float32Array(this.max);
61:     this.baseCol = [];
62:     for (let i = 0; i < this.max; i++) {
63:       this.pos[i * 3 + 1] = -999;
64:       this.life[i] = 0;
65:       this.baseCol.push(new THREE.Color());
66:     }
67:     const geo = new THREE.BufferGeometry();
68:     geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
69:     geo.setAttribute('color', new THREE.BufferAttribute(this.col, 3));
70:     const mat = new THREE.PointsMaterial({
71:       size: 0.26, map: glowTexture('#ffffff', 0.5), vertexColors: true,
72:       transparent: true, opacity: 0.95, depthWrite: false, sizeAttenuation: true,
73:     });
74:     this.points = new THREE.Points(geo, mat);
75:     this.points.frustumCulled = false;
76:     this.geo = geo;
77:     scene.add(this.points);
78:     this.cursor = 0;
79:   }
80: 
81:   emit(pos, color, count = 10, speed = 2.4, up = 2.4) {
82:     const c = new THREE.Color(color);
83:     for (let n = 0; n < count; n++) {
84:       const i = this.cursor++ % this.max;
85:       this.life[i] = this.maxLife[i] = rand(0.35, 0.85);
86:       this.pos[i * 3] = pos.x + rand(-0.2, 0.2);
87:       this.pos[i * 3 + 1] = pos.y + rand(0, 0.4);
88:       this.pos[i * 3 + 2] = pos.z + rand(-0.2, 0.2);
89:       const a = rand(0, Math.PI * 2), s = rand(0.2, speed);
90:       this.vel[i * 3] = Math.cos(a) * s;
91:       this.vel[i * 3 + 1] = rand(0.6, up);
92:       this.vel[i * 3 + 2] = Math.sin(a) * s;
93:       this.baseCol[i].copy(c);
94:       this.col[i * 3] = c.r; this.col[i * 3 + 1] = c.g; this.col[i * 3 + 2] = c.b;
95:     }
96:   }
97: 
98:   update(dt) {
99:     let dirty = false;
100:     for (let i = 0; i < this.max; i++) {
101:       if (this.life[i] <= 0) continue;
102:       this.life[i] -= dt;
103:       dirty = true;
104:       if (this.life[i] <= 0) {
105:         this.pos[i * 3 + 1] = -999;
106:         continue;
107:       }
108:       this.vel[i * 3 + 1] -= 7.5 * dt;
109:       this.pos[i * 3] += this.vel[i * 3] * dt;
110:       this.pos[i * 3 + 1] += this.vel[i * 3 + 1] * dt;
111:       this.pos[i * 3 + 2] += this.vel[i * 3 + 2] * dt;
112:       const f = clamp(this.life[i] / this.maxLife[i], 0, 1);
113:       this.col[i * 3] = this.baseCol[i].r * f;
114:       this.col[i * 3 + 1] = this.baseCol[i].g * f;
115:       this.col[i * 3 + 2] = this.baseCol[i].b * f;
116:     }
117:     if (dirty) {
118:       this.geo.attributes.position.needsUpdate = true;
119:       this.geo.attributes.color.needsUpdate = true;
120:     }
121:   }
122: }
