363:   // ---------------- save ----------------
364:   save() {
365:     if (this.mode !== 'play') return;
366:     const s = this.state;
367:     const data = {
368:       ...s,
369:       playerPos: { x: this.player.pos.x, z: this.player.pos.z },
370:       playerFacing: this.player.facing,
371:       plots: this.world.plots.map((p) => ({
372:         tilled: p.tilled,
373:         watered: p.watered,
374:         crop: p.crop ? { type: p.crop.type, grown: p.crop.grown } : null,
375:       })),
376:     };
377:     try { localStorage.setItem(SAVE_KEY, JSON.stringify(data)); } catch {}
