379: 
380:   readSave() {
381:     try {
382:       const raw = localStorage.getItem(SAVE_KEY);
383:       if (!raw) return null;
384:       const data = JSON.parse(raw);
385:       if (!data || data.version !== 1) return null;
386:       return data;
387:     } catch { return null; }
