389: 
390:   loadState(data) {
391:     const base = defaultState();
392:     this.state = {
393:       ...base, ...data,
394:       seeds: { ...base.seeds, ...(data.seeds || {}) },
395:       crops: { ...base.crops, ...(data.crops || {}) },
396:       stats: { ...base.stats, ...(data.stats || {}) },
397:       flags: { ...base.flags, ...(data.flags || {}) },
398:       quests: { ...(data.quests || {}) },
399:       blessing: data.blessing || 0,
400:       sprinklerCount: data.sprinklerCount || 0,
401:     };
402:     this.soundOn = this.state.soundOn !== false;
403:     this.world.setWeather(this.state.weather === 'rain' ? 'rain' : 'clear');
404:     this.world.day = this.state.day;
405:     this.world.newDay(this.state.day);
406:     for (let i = 0; i < (data.plots?.length || 0); i++) {
407:       const pd = data.plots[i];
408:       const p = this.world.plots[i];
409:       if (!pd || !p) continue;
410:       p.tilled = !!pd.tilled;
411:       p.watered = !!pd.watered;
412:       if (pd.crop && CROPS[pd.crop.type]) {
413:         p.crop = { type: pd.crop.type, grown: pd.crop.grown || 0, growDays: CROPS[pd.crop.type].grow, watered: p.watered };
414:       } else p.crop = null;
415:       this.world.refreshPlot(p);
416:     }
417:     for (let i = 0; i < this.state.sprinklerCount; i++) this.world.addSprinkler(i);
418:   }
