420:   // ---------------- loop ----------------
421:   loop() {
422:     requestAnimationFrame(this.loop);
423:     let dt = this.clock.getDelta();
424:     if (dt > 0.06) dt = 0.06;
425:     this.update(dt);
426:     this.composer.render();
427:   }
428: 
429:   update(dt) {
430:     this.frames++;
431:     this.fpsAccum += dt;
432:     if (this.fpsAccum > 2) {
433:       const fps = this.frames / this.fpsAccum;
434:       if (fps < 26 && !this.lowFps) {
435:         this.lowFps = true;
436:         this.renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 1.1));
437:         this.bloom.enabled = false;
438:       }
439:       this.fpsAccum = 0; this.frames = 0;
440:     }
441: 
442:     const playing = this.mode === 'play' && !this.paused && !this.transitioning;
443:     if (this.mode === 'play' && playing) {
444:       this.state.hours += dt * 0.042;
445:       if (this.state.hours >= 24) {
446:         this.state.hours = 24;
447:         this.sleep(true);
448:       }
449:       this.updateMovement(dt);
450:       this.updateTarget();
451:       this.updateActionsUI();
452:       this.invuln = Math.max(0, this.invuln - dt);
453:       if (this.shake > 0) this.shake = Math.max(0, this.shake - dt * 2.2);
454:       this.stepAccum -= dt;
455:       if (this.player.moving && this.stepAccum <= 0) {
456:         this.stepAccum = 0.36;
457:         this.audio.sfx('step');
458:       }
459:     } else {
460:       this.player.moving = false;
461:       this.player.update(dt, false, 0, this.state.hours);
462:       this.player.faceTowards(this.player.pos.x + Math.sin(this.player.facing), this.player.pos.z + Math.cos(this.player.facing), 1);
463:     }
464: 
465:     this.player.update(dt, this.player.moving, 4.4, this.state.hours);
466:     this.slimes.update(playing ? dt : 0, this.player.pos, this);
467:     this.particles.update(dt);
468:     this.world.update(dt, this.state.hours, this.state.weather, this.player.pos);
469:     this.updateCamera(dt, false);
470: 
471:     if (playing) {
472:       this.autosaveAccum = (this.autosaveAccum || 0) + dt;
473:       if (this.autosaveAccum > 20) { this.autosaveAccum = 0; this.save(); }
474:     }
475:     this.uiAccum += dt;
476:     if (this.uiAccum > 0.12) {
477:       this.uiAccum = 0;
478:       if (this.mode === 'play') this.ui.update(this.state);
479:     }
480:     this.ambientAccum += dt;
481:     if (this.ambientAccum > 1) {
482:       this.ambientAccum = 0;
483:       if (this.mode === 'play') this.audio.updateAmbient(this.state.hours, this.state.hours > 19 || this.state.hours < 6);
484:     }
485: 
486:     if (playing) {
487:       if (!this.state.flags.tutTilled && this.state.hours > 7.4) {
488:         // no-op ambient hint handled contextually
489:       }
490:       if (this.state.hours > 19.5 && !this.state.flags.nightHint) {
491:         this.state.flags.nightHint = true;
492:         this.ui.showHint('Dusk falls. Slimes grow bold — or sleep at the cottage.', 5000);
493:       }
494:       if (this.state.hours > 23.2 && !this.state.flags.midnightHint) {
495:         this.state.flags.midnightHint = true;
496:         this.ui.showHint('Midnight approaches. Head home to sleep.', 5000);
497:       }
498:     }
499:   }
500: 
501:   // ---------------- movement ----------------
502:   updateMovement(dt) {
503:     let f = 0, s = 0;
504:     if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) f += 1;
505:     if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) f -= 1;
506:     if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) s += 1;
507:     if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) s -= 1;
508:     if (Math.abs(this.joystick.y) > 0.16) f += -this.joystick.y;
509:     if (Math.abs(this.joystick.x) > 0.16) s += this.joystick.x;
510:     let len = Math.hypot(f, s);
511:     if (len > 1) { f /= len; s /= len; len = 1; }
512:     const moving = len > 0.05;
513:     this.player.moving = moving;
514:     if (!moving) return;
515: 
516:     const yaw = this.cameraYaw;
517:     const speed = 4.5;
518:     const vx = (-Math.sin(yaw) * f + Math.cos(yaw) * s) * speed;
519:     const vz = (-Math.cos(yaw) * f - Math.sin(yaw) * s) * speed;
520:     this.player.pos.x += vx * dt;
521:     this.player.pos.z += vz * dt;
522:     this.resolveCollisions(this.player.pos);
523:     const r = Math.hypot(this.player.pos.x, this.player.pos.z);
524:     if (r > 54) {
525:       this.player.pos.x *= 54 / r;
526:       this.player.pos.z *= 54 / r;
527:     }
528:     this.player.pos.y = this.world.height(this.player.pos.x, this.player.pos.z);
529:     this.player.faceDirection(vx, vz, dt);
530:   }
531: 
532:   resolveCollisions(pos) {
533:     const R = 0.38;
534:     for (const c of this.world.colliders) {
535:       if (c.boundary) continue;
536:       if (c.tree && !c.tree.active) continue;
537:       if (c.rock && !c.rock.active) continue;
538:       if (c.kind === 'stone') continue;
539:       const dx = pos.x - c.x, dz = pos.z - c.z;
540:       const d = Math.hypot(dx, dz);
541:       const min = c.r + R;
542:       if (d < min && d > 0.0001) {
543:         pos.x = c.x + (dx / d) * min;
544:         pos.z = c.z + (dz / d) * min;
545:       }
546:     }
547:     for (const b of this.world.boxes) {
548:       const nx = clamp(pos.x, b.minX, b.maxX);
549:       const nz = clamp(pos.z, b.minZ, b.maxZ);
550:       const dx = pos.x - nx, dz = pos.z - nz;
551:       const d = Math.hypot(dx, dz);
552:       if (d < R) {
553:         if (d > 0.0001) {
554:           pos.x = nx + (dx / d) * R;
555:           pos.z = nz + (dz / d) * R;
556:         } else {
557:           // inside: push out shortest side
558:           const dl = pos.x - b.minX, dr = b.maxX - pos.x, dt = pos.z - b.minZ, db = b.maxZ - pos.z;
559:           const m = Math.min(dl, dr, dt, db);
560:           if (m === dl) pos.x = b.minX - R;
561:           else if (m === dr) pos.x = b.maxX + R;
562:           else if (m === dt) pos.z = b.minZ - R;
563:           else pos.z = b.maxZ + R;
564:         }
565:       }
566:     }
567:     for (const sg of this.world.segments) {
568:       const res = distToSegment(pos.x, pos.z, sg.ax, sg.az, sg.bx, sg.bz);
569:       const min = R + sg.r;
570:       if (res.dist < min && res.dist > 0.0001) {
571:         pos.x += (res.nx / res.dist) * (min - res.dist);
572:         pos.z += (res.nz / res.dist) * (min - res.dist);
573:       }
574:     }
575:     // keep out of the pond
576:     const pd = Math.hypot(pos.x - LAYOUT.pond.x, pos.z - LAYOUT.pond.z);
577:     if (pd < 5.6) {
578:       const k = 5.6 / Math.max(pd, 0.001);
579:       pos.x = LAYOUT.pond.x + (pos.x - LAYOUT.pond.x) * k;
580:       pos.z = LAYOUT.pond.z + (pos.z - LAYOUT.pond.z) * k;
581:     }
582:   }
