929:       if (p.crop.watered) {
930:         if (p.crop.grown < p.crop.growDays) {
931:           p.crop.grown++;
932:           grown++;
933:         }
934:       }
935:       p.crop.watered = false;
936:       p.watered = false;
937:     }
938:     s.day++;
939:     s.hours = 6.15;
940:     s.season = 'Spring';
941:     let rain = Math.random() < 0.34;
