952:     for (const sp of this.world.sprinklers) {
953:       for (const p of this.world.plots) {
954:         if (!p.crop) continue;
955:         if (Math.hypot(p.x - sp.x, p.z - sp.z) < 3.1) {
956:           p.crop.watered = true;
957:           p.watered = true;
