190:     this.renderer.setPixelRatio(Math.min(devicePixelRatio || 1, isTouch() ? 1.5 : 1.8));
191:     this.renderer.setSize(innerWidth, innerHeight);
192:     this.renderer.shadowMap.enabled = true;
193:     this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
194:     this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
195:     this.renderer.toneMappingExposure = 1.08;
