239:     const cv = this.renderer.domElement;
240:     cv.addEventListener('contextmenu', (e) => e.preventDefault());
241:     cv.addEventListener('pointerdown', (e) => {
242:       if (this.mode !== 'play' || this.paused) return;
243:       if (e.pointerType === 'mouse' && e.button !== 0) return;
244:       this.drag = { id: e.pointerId, x: e.clientX, y: e.clientY };
245:       try { cv.setPointerCapture(e.pointerId); } catch {}
246:     });
247:     cv.addEventListener('pointermove', (e) => {
248:       if (!this.drag || e.pointerId !== this.drag.id) return;
249:       const dx = e.clientX - this.drag.x;
250:       const dy = e.clientY - this.drag.y;
251:       this.drag.x = e.clientX; this.drag.y = e.clientY;
252:       this.cameraYaw -= dx * 0.0055;
253:       this.cameraPitch = clamp(this.cameraPitch + dy * 0.0028, 0.46, 1.02);
254:     });
255:     const dragEnd = (e) => {
256:       if (this.drag && e.pointerId === this.drag.id) this.drag = null;
257:     };
258:     cv.addEventListener('pointerup', dragEnd);
259:     cv.addEventListener('pointercancel', dragEnd);
260:     cv.addEventListener('wheel', (e) => {
261:       if (this.mode !== 'play') return;
262:       e.preventDefault();
263:       this.cameraDist = clamp(this.cameraDist + Math.sign(e.deltaY) * 1.2, 10, 26);
264:     }, { passive: false });
