139:     $('hud-weather').textContent = s.weather === 'rain' ? '🌧 Rain' : s.hours > 19 || s.hours < 6 ? '🌙 Clear' : '☀ Clear';
140:     const h = Math.floor(s.hours) % 24;
141:     const m = Math.floor((s.hours % 1) * 60);
142:     const ampm = h >= 12 ? 'PM' : 'AM';
143:     const h12 = h % 12 === 0 ? 12 : h % 12;
144:     $('hud-clock').textContent = `${h12}:${String(m).padStart(2, '0')} ${ampm}`;
145:     $('daytrack').style.width = `${Math.min(100, Math.max(0, ((s.hours - 6) / 18) * 100))}%`;
146:     $('hud-gold').textContent = Math.floor(s.gold);
147:     $('hud-essence').textContent = Math.floor(s.essence);
148:     $('hud-wood').textContent = Math.floor(s.wood);
149:     $('hud-stone').textContent = Math.floor(s.stone);
150:     $('bar-health').style.width = `${Math.max(0, (s.health / s.maxHealth) * 100)}%`;
151:     $('bar-energy').style.width = `${Math.max(0, (s.energy / s.maxEnergy) * 100)}%`;
152:     $('bar-health').parentElement.classList.toggle('low', s.health / s.maxHealth < 0.3);
153:     $('bar-energy').parentElement.classList.toggle('low', s.energy / s.maxEnergy < 0.25);
154:     this.updateSeeds(s);
155:     this.updateQuestChip(s);
156:     // compass: point at wizard tower
157:     const dx = 15.5 - this.game.player.pos.x, dz = 6.5 - this.game.player.pos.z;
158:     const ang = Math.atan2(dx, dz) - this.game.cameraYaw;
