import { spawn } from 'node:child_process';
import { writeFile } from 'node:fs/promises';
const browser = spawn('/usr/bin/chromium', ['--headless', '--no-sandbox', '--disable-gpu', '--enable-unsafe-swiftshader', '--remote-debugging-port=9223', '--user-data-dir=/tmp/opencode/chrome-jpeg', 'about:blank'], { stdio: 'ignore' });
try {
  let endpoint;
  for (let i = 0; i < 50; i++) {
    try { endpoint = await fetch('http://127.0.0.1:9223/json/new?http://localhost:3002', { method: 'PUT' }).then(r => r.json()); break; } catch {}
    await new Promise(resolve => setTimeout(resolve, 200));
  }
  if (!endpoint?.webSocketDebuggerUrl) throw new Error('Chromium debugging endpoint unavailable');
  const ws = new WebSocket(endpoint.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let id = 0;
  const pending = new Map();
  ws.onmessage = event => {
    const message = JSON.parse(event.data);
    if (pending.has(message.id)) { pending.get(message.id)(message); pending.delete(message.id); }
  };
  const send = (method, params = {}) => new Promise(resolve => { const requestId = ++id; pending.set(requestId, resolve); ws.send(JSON.stringify({ id: requestId, method, params })); });
  await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
  await send('Page.enable');
  await send('Page.navigate', { url: 'http://localhost:3002' });
  await new Promise(resolve => setTimeout(resolve, 9000));
  const result = await send('Page.captureScreenshot', { format: 'jpeg', quality: 82, fromSurface: true });
  await writeFile('/tmp/opencode/emberfall.jpg', Buffer.from(result.result.data, 'base64'));
  ws.close();
} finally { browser.kill('SIGTERM'); }
EOF
