501:   // ---------------- movement ----------------
502:   updateMovement(dt) {
503:     let f = 0, s = 0;
504:     if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) f += 1;
505:     if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) f -= 1;
506:     if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) s += 1;
507:     if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) s -= 1;
508:     if (Math.abs(this.joystick.y) > 0.16) f += -this.joystick.y;
509:     if (Math.abs(this.joystick.x) > 0.16) s += this.joystick.x;
510:     let len = Math.hypot(f, s);
511:     if (len > 1) { f /= len; s /= len; len = 1; }
512:     const moving = len > 0.05;
513:     this.player.moving = moving;
514:     if (!moving) return;
515: 
516:     const yaw = this.cameraYaw;
517:     const speed = 4.5;
518:     const vx = (-Math.sin(yaw) * f + Math.cos(yaw) * s) * speed;
519:     const vz = (-Math.cos(yaw) * f - Math.sin(yaw) * s) * speed;
520:     this.player.pos.x += vx * dt;
521:     this.player.pos.z += vz * dt;
522:     this.resolveCollisions(this.player.pos);
523:     const r = Math.hypot(this.player.pos.x, this.player.pos.z);
524:     if (r > 54) {
525:       this.player.pos.x *= 54 / r;
526:       this.player.pos.z *= 54 / r;
527:     }
528:     this.player.pos.y = this.world.height(this.player.pos.x, this.player.pos.z);
529:     this.player.faceDirection(vx, vz, dt);
530:   }
531: 
532:   resolveCollisions(pos) {
533:     const R = 0.38;
534:     for (const c of this.world.colliders) {
535:       if (c.boundary) continue;
536:       if (c.tree && !c.tree.active) continue;
537:       if (c.rock && !c.rock.active) continue;
538:       if (c.kind === 'stone') continue;
539:       const dx = pos.x - c.x, dz = pos.z - c.z;
540:       const d = Math.hypot(dx, dz);
541:       const min = c.r + R;
542:       if (d < min && d > 0.0001) {
543:         pos.x = c.x + (dx / d) * min;
544:         pos.z = c.z + (dz / d) * min;
545:       }
546:     }
547:     for (const b of this.world.boxes) {
548:       const nx = clamp(pos.x, b.minX, b.maxX);
549:       const nz = clamp(pos.z, b.minZ, b.maxZ);
550:       const dx = pos.x - nx, dz = pos.z - nz;
551:       const d = Math.hypot(dx, dz);
552:       if (d < R) {
553:         if (d > 0.0001) {
554:           pos.x = nx + (dx / d) * R;
555:           pos.z = nz + (dz / d) * R;
556:         } else {
557:           // inside: push out shortest side
558:           const dl = pos.x - b.minX, dr = b.maxX - pos.x, dt = pos.z - b.minZ, db = b.maxZ - pos.z;
559:           const m = Math.min(dl, dr, dt, db);
560:           if (m === dl) pos.x = b.minX - R;
561:           else if (m === dr) pos.x = b.maxX + R;
562:           else if (m === dt) pos.z = b.minZ - R;
563:           else pos.z = b.maxZ + R;
564:         }
565:       }
566:     }
567:     for (const sg of this.world.segments) {
568:       const res = distToSegment(pos.x, pos.z, sg.ax, sg.az, sg.bx, sg.bz);
569:       const min = R + sg.r;
570:       if (res.dist < min && res.dist > 0.0001) {
571:         pos.x += (res.nx / res.dist) * (min - res.dist);
572:         pos.z += (res.nz / res.dist) * (min - res.dist);
573:       }
574:     }
575:     // keep out of the pond
576:     const pd = Math.hypot(pos.x - LAYOUT.pond.x, pos.z - LAYOUT.pond.z);
577:     if (pd < 5.6) {
578:       const k = 5.6 / Math.max(pd, 0.001);
579:       pos.x = LAYOUT.pond.x + (pos.x - LAYOUT.pond.x) * k;
580:       pos.z = LAYOUT.pond.z + (pos.z - LAYOUT.pond.z) * k;
581:     }
582:   }
