1036:     this.state.health = Math.max(0, this.state.health - amount);
1037:     this.invuln = 1.15;
1038:     this.shake = 0.22;
1039:     this.audio.sfx('hurt');
1040:     this.ui.float(`-${amount} ❤`, new THREE.Vector3(this.player.pos.x, 2.1, this.player.pos.z), 'dmg');
1041:     const dx = this.player.pos.x - sx, dz = this.player.pos.z - sz;
1042:     const d = Math.hypot(dx, dz) || 1;
1043:     this.player.pos.x += (dx / d) * 0.7;
