174:       if (farmD < 1.2) tmp.lerp(cDirt, 0.22 * (1 - Math.max(farmD, 0) / 1.2));
175:       if (Math.abs(x) < 8.1 && Math.abs(z) < 8.1) tmp.lerp(new THREE.Color('#7c9b52'), 0.32);
176:       const rr = Math.hypot(x, z);
177:       if (rr > 44) tmp.lerp(new THREE.Color('#7f8d84'), smoothstep(44, 82, rr) * 0.5);
178:       const jitter = (n2 - 0.5) * 0.07;
179:       colors[i * 3] = clamp(tmp.r + jitter, 0, 1);
180:       colors[i * 3 + 1] = clamp(tmp.g + jitter, 0, 1);
181:       colors[i * 3 + 2] = clamp(tmp.b + jitter * 0.6, 0, 1);
182:     }
183:     geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
184:     geo.computeVertexNormals();
185:     const mat = vcMat({ roughness: 1 });
186:     const mesh = new THREE.Mesh(geo, mat);
187:     mesh.receiveShadow = true;
188:     mesh.name = 'terrain';
189:     this.scene.add(mesh);
190:     this.terrain = mesh;
191:   }
