193:   // =========================================================== paths
194:   buildPaths() {
195:     const curves = [
196:       [[-11.5, -10.2], [-10.1, -7.6], [-8.4, -3.8], [-8.4, 5.4], [-6.3, 8.6], [-2.0, 11.1], [0, 11.7], [5.2, 11.5], [10.2, 9.8], [13.2, 8.2], [15.5, 8.0]],
197:       [[0, 11.7], [-5.2, 11.4], [-10.5, 10.5], [-14.2, 8.9], [-16.2, 7.3]],
198:       [[15.5, 8.0], [19.4, 8.5], [22.5, 10.5]],
199:     ];
200:     for (const pts of curves) {
201:       const curve = new THREE.CatmullRomCurve3(pts.map(([x, z]) => new THREE.Vector3(x, 0, z)));
202:       const N = 60;
203:       const half = 1.35;
204:       const positions = [];
205:       const colors = [];
206:       const indices = [];
207:       const up = new THREE.Vector3(0, 1, 0);
208:       for (let i = 0; i <= N; i++) {
209:         const t = i / N;
210:         const p = curve.getPoint(t);
211:         const tan = curve.getTangent(t);
212:         const side = new THREE.Vector3(-tan.z, 0, tan.x).normalize();
213:         for (const s of [-1, 1]) {
214:           const px = p.x + side.x * half * s;
215:           const pz = p.z + side.z * half * s;
216:           const y = this.height(px, pz) + 0.035;
217:           positions.push(px, y, pz);
218:           const n = noise2(px * 1.7, pz * 1.7);
219:           const c = new THREE.Color('#8d7550').lerp(new THREE.Color('#a58c62'), n);
220:           colors.push(c.r, c.g, c.b);
221:         }
222:         if (i < N) {
223:           const a = i * 2;
224:           indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
225:         }
226:         this.pathSamples.push({ x: p.x, z: p.z });
227:       }
228:       const geo = new THREE.BufferGeometry();
229:       geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
230:       geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
231:       geo.setIndex(indices);
232:       geo.computeVertexNormals();
233:       const mat = vcMat({ roughness: 1, polygonOffset: true, polygonOffsetFactor: -2 });
234:       const mesh = new THREE.Mesh(geo, mat);
235:       mesh.receiveShadow = true;
236:       this.scene.add(mesh);
237:     }
238:   }
