240:   nearPath(x, z, r = 2.2) {
241:     for (const p of this.pathSamples) {
242:       if (Math.abs(p.x - x) < r && Math.abs(p.z - z) < r && distToSegment(x, z, p.x, p.z, p.x, p.z).dist < r) return true;
243:     }
244:     return false;
245:   }
