635:   describePlot(t) {
636:     const p = t.plot;
637:     if (!p.tilled) {
638:       t.icon = '🪓'; t.label = 'Till'; t.prompt = 'Till the soil'; t.enabled = true;
639:       return;
640:     }
641:     if (!p.crop) {
642:       const type = this.state.selectedSeed;
643:       const c = CROPS[type];
644:       const n = this.state.seeds[type] || 0;
645:       t.icon = '🌱'; t.label = n > 0 ? 'Plant' : 'No seed';
646:       t.prompt = n > 0 ? `Plant ${c.name} (${n} left)` : `No ${c.name} seeds — visit Zephyr`;
647:       t.enabled = n > 0;
648:       return;
649:     }
650:     const c = CROPS[p.crop.type];
651:     if (p.crop.grown >= p.crop.growDays) {
652:       t.icon = '🌾'; t.label = 'Harvest'; t.prompt = `Harvest ${c.name}`; t.enabled = true;
653:     } else if (!p.crop.watered) {
654:       t.icon = '💧'; t.label = 'Water'; t.prompt = `Water ${c.name}`; t.enabled = true;
655:     } else {
656:       t.icon = '⌛'; t.label = 'Growing';
657:       t.prompt = `${c.name} · ${p.crop.grown}/${p.crop.growDays} nights · watered`;
658:       t.enabled = false;
659:     }
660:   }
