111:       const dist = Math.hypot(dx, dz);
112:       s.timer -= dt;
113:       if (s.cooldown > 0) s.cooldown -= dt;
114:       if (s.hurt > 0) s.hurt -= dt;
115: 
116:       // knockback
117:       if (Math.abs(s.knockX) + Math.abs(s.knockZ) > 0.01) {
118:         s.x += s.knockX * dt;
119:         s.z += s.knockZ * dt;
