121:         s.knockZ *= Math.pow(0.02, dt);
122:       }
123: 
124:       let moving = false;
125:       if (dist < 7.2 && game.state.hours > 17.5) s.phase = 'chase';
126:       if (dist < 5.2) s.phase = 'chase';
127:       if (s.phase === 'chase' && dist > 11) s.phase = 'wander';
128: 
129:       if (s.phase === 'chase' && dist > 0.01) {
130:         const sp = s.speed * (dist < 2 ? 0.8 : 1);
131:         s.x += (dx / dist) * sp * dt;
132:         s.z += (dz / dist) * sp * dt;
133:         moving = true;
