139:         }
140:       } else if (s.timer <= 0) {
141:         s.timer = rand(2.2, 5.2);
142:         const a = rand(0, Math.PI * 2), r = rand(2, 8);
143:         s.wander.x = s.homeX + Math.cos(a) * r;
144:         s.wander.z = s.homeZ + Math.sin(a) * r;
145:       } else {
146:         const wdx = s.wander.x - s.x, wdz = s.wander.z - s.z;
147:         const wd = Math.hypot(wdx, wdz);
148:         if (wd > 0.4) {
149:           s.x += (wdx / wd) * s.speed * 0.42 * dt;
150:           s.z += (wdz / wd) * s.speed * 0.42 * dt;
